export const meta = {
  name: 'sluice-F2',
  description: 'Build v1.4 item F2 (Summon on the fly): plan, build, adversarial review, fix',
  phases: [{ title: 'Plan' }, { title: 'Build' }, { title: 'Review' }, { title: 'Fix' }, { title: 'Re-review' }],
}
const WF = 'docs/progress/v1.4/work/F2/'
const common = (role, round) => `sluice: tranche=v1.4 item=F2 role=${role} tier=large round=${round} parallel=no
Work folder: ${WF}
Scope doc: docs/27-v1.4.md (item: ### F2 Summon on the fly)
Start commit: 61e4958
Nobody is watching this run: no one can answer a question. Take decisions from docs/27-v1.4.md's Decisions where they cover it; otherwise use your judgment and record the decision in your record (and the packet/build record). Fixture data only (INV-18), never a real PAT, the app never writes to ADO. Never commit, push or change branches.
`
const VERDICT = { type: 'object', properties: {
  verdict: { type: 'string', description: 'accept | fix | replan' },
  blockers: { type: 'number' }, majors: { type: 'number' }, minors: { type: 'number' },
  summary: { type: 'string' } }, required: ['verdict', 'blockers', 'majors', 'minors', 'summary'] }

phase('Plan')
const plan = await agent(common('planner', 1) + `Task: write ${WF}packet.md and plan-1.json for F2, per the item contract. Read F1's work folder (docs/progress/v1.4/work/F1/) for the shape of a good packet. Decide the approach (pursue passing through the spot, one call blip synchronised with the station act within 50 ms, hold and fly-back removed, carry on to next sortie or rest, reduced motion plays at place, plate for NOTE_MIN_MS), list files with line ranges, acceptance (gallery cell full+reduced motion, unit test, 15 §7 row + docTables, schedule goldens named, ledger saving per pod), and the mapped e2e specs from tests/README.md.`, { label: 'planner', phase: 'Plan', agentType: 'planner' })

phase('Build')
const build = await agent(common('builder', 1) + `Task: build F2 from ${WF}packet.md. Write build-1.json. Run typecheck, lint, unit tests, the mapped e2e specs from the packet (npm run e2e:spec -- <names>) and npm run e2e:keystone. Update goldens only where F2 meant to move them, and name each change in the build record. Update the ledger (scripts/pacing-ledger.ts / docs/progress/v1.4/pacing-ledger.*) so it shows the saving per pod. Update docs 13 §6, 05 §8, 15 §7 as the item names.`, { label: 'builder', phase: 'Build', agentType: 'builder' })

phase('Review')
const rev = await agent(common('reviewer', 1) + `Task: a fresh, adversarial review of the uncommitted diff (git diff 61e4958 plus untracked files) against ${WF}packet.md's acceptance, the item's Decided text and the project rules (02 §1 invariants, R1–R14). Verify claims yourself: run the unit tests and the relevant e2e specs; check the 50 ms blip-to-act test is real, no hold remains, reduced motion, goldens' diffs are intended, docTables passes, the ledger shows per-pod savings. Write review-1.md and review-1.json. Return your verdict and finding counts.`, { label: 'reviewer', phase: 'Review', agentType: 'reviewer', schema: VERDICT })
log(`review-1: ${rev && rev.verdict} B${rev && rev.blockers} M${rev && rev.majors} m${rev && rev.minors}`)

let rev2 = null, fix = null
if (rev && (rev.blockers + rev.majors + rev.minors) > 0) {
  phase('Fix')
  fix = await agent(common('fixer', 1) + `Task: fix the Blocker and Major findings of ${WF}review-1.md, and its cheap Minors. Write fix-1.json. Re-run typecheck, lint, unit tests and the mapped e2e specs plus npm run e2e:keystone.`, { label: 'fixer', phase: 'Fix', agentType: 'fixer' })
  if (rev.blockers + rev.majors > 0) {
    phase('Re-review')
    rev2 = await agent(common('reviewer', 2) + `Task: fresh review of the fixes for ${WF}review-1.md's findings (see fix-1.json), and of the whole diff against git 61e4958 for regressions. Write review-2.md and review-2.json. Return verdict and counts.`, { label: 'reviewer-2', phase: 'Re-review', agentType: 'reviewer', schema: VERDICT })
  }
}
return { plan, build, rev, fix, rev2 }

