import { test, type ElectronApplication, type Page } from '@playwright/test';
import { launchGallery } from './launch';
let app: ElectronApplication; let page: Page;
test.beforeAll(async () => { ({ app, page } = await launchGallery()); await page.waitForFunction(() => Boolean(window.__starChartGallery), undefined, { timeout: 30_000 }); await page.evaluate(() => window.__starChartGallery!.ready); });
test.afterAll(async () => { await app.close(); });
type W = Window & { __starChartGalleryDemos?: { list(): { rule: string; state: string; peak: number }[]; setReduced(on: boolean): void } };
test('f2 stills', async () => {
  test.setTimeout(240_000);
  const list = await page.evaluate(() => (window as W).__starChartGalleryDemos!.list().map((d) => d.rule));
  const rule = list.find((r) => r === 'facility.enter') ?? list.find((r) => r.startsWith('facility.enter'))!;
  const cell = page.locator(`[data-art="maneuvers:${rule}"]`).locator('xpath=ancestor::figure[1]');
  await cell.scrollIntoViewIfNeeded();
  for (const [reduced, file] of [[false, 'f2-jumpin-full'], [true, 'f2-jumpin-reduced']] as const) {
    await page.evaluate((r) => (window as W).__starChartGalleryDemos!.setReduced(r), reduced);
    await page.waitForFunction((x) => (window as W).__starChartGalleryDemos!.list().find((d) => d.rule === x)?.state === 'play', rule, { timeout: 60_000, polling: 20 });
    await page.waitForTimeout(reduced ? 300 : 700);
    await cell.screenshot({ path: `/tmp/${file}.png` });
  }
});
E
npm run e2e:spec -- zz-f2-stills 2>&1 | tail -8; ls /tmp/f2-*

